require __DIR__.'/auth.php';requireAdmin();require dirname(__DIR__).'/includes/bootstrap.php';
require dirname(__DIR__).'/Config/catalog.php';
require dirname(__DIR__).'/Config/property-documents.php';
require_once dirname(__DIR__).'/Config/blog.php';
$errors=[];$data=[];$types=catalogNames('property_type');$locations=catalogNames('location');
$fields=['title','city','address','description','type','purpose','price','beds','baths','area','amenities','featured','nearest_locations','subtitle','state','zip','balconies','floors','parking','youtube_videos','youtube_shorts'];foreach($fields as $field)$data[$field]=is_string($_POST[$field]??null)?trim($_POST[$field]):'';
if($_SERVER['REQUEST_METHOD']==='POST'){
 adminCsrf();
 foreach(['title'=>150,'city'=>100,'address'=>300,'description'=>10000,'amenities'=>2000,'nearest_locations'=>4000,'subtitle'=>200,'state'=>100,'zip'=>30,'parking'=>100,'youtube_videos'=>2000,'youtube_shorts'=>2000] as $key=>$max){if(in_array($key,['title','city','description'],true)&&$data[$key]==='')$errors[]=ucfirst($key).' is required.';if(mb_strlen($data[$key])>$max)$errors[]=ucfirst($key).' is too long.';}
 if(!in_array($data['city'],$locations,true))$errors[]='Choose a location from the catalog.';
 if(!in_array($data['type'],$types,true)||!in_array($data['purpose'],['Rent','Sell'],true))$errors[]='Choose a valid type and purpose.';
 foreach(['price'=>100000000000,'area'=>100000000,'beds'=>100,'baths'=>100] as $key=>$max){if(!is_numeric($data[$key])||(float)$data[$key]<0||(float)$data[$key]>$max||($key==='area'&&(float)$data[$key]<=0)|| (in_array($key,['beds','baths'],true)&&floor((float)$data[$key])!=(float)$data[$key]))$errors[]='Enter a valid '. $key.'.';}
 $pricingUploads=[];try{$pricingUploads=propertyDocumentUploads($_FILES['pricing_documents']??[]);}catch(InvalidArgumentException $e){$errors[]=$e->getMessage();}
 if(count(preg_split('/\R/',trim($data['nearest_locations'])))>20)$errors[]='Add up to 20 nearest locations.';
 $galleryUploads=[];try{$galleryUploads=propertyDocumentUploads($_FILES['gallery']??[]);foreach($galleryUploads as $image){if($image['type']!=='image')throw new InvalidArgumentException('Gallery accepts images only.');}}catch(InvalidArgumentException $e){$errors[]='Gallery: '.$e->getMessage();}
 $videos=[];foreach(['youtube_videos'=>'video','youtube_shorts'=>'short'] as $field=>$videoType){foreach(preg_split('/\R/',$data[$field]) as $url){if(trim($url)==='')continue;$id=blogYoutubeId(trim($url));if(!$id){$errors[]='Enter valid YouTube links, one per line.';break;}$videos[]=['url'=>'https://www.youtube.com/watch?v='.$id,'type'=>$videoType,'title'=>$videoType==='short'?'Property short':'Property video'];}}if(count($videos)>10)$errors[]='Add up to 10 YouTube videos.';
 foreach(['balconies','floors'] as $field){if($data[$field]!==''&&(!ctype_digit($data[$field])||(int)$data[$field]>200))$errors[]='Enter a valid '.$field.'.';}
 $upload=$_FILES['photo']??null;$extension='';
 if(!$upload||$upload['error']!==UPLOAD_ERR_OK)$errors[]='Upload a cover photo (JPEG, PNG or WebP, max 5 MB).';
 else{ $mime=(new finfo(FILEINFO_MIME_TYPE))->file($upload['tmp_name']);$extension=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'][$mime]??'';$size=@getimagesize($upload['tmp_name']);if(!$extension||!$size||$upload['size']>5*1024*1024||$size[0]*$size[1]>40000000)$errors[]='Photo must be a valid JPEG, PNG or WebP up to 5 MB and 40 megapixels.'; }
 if(!$errors){
  $filename=bin2hex(random_bytes(16)).'.'.$extension;$target=dirname(__DIR__).'/assets/uploads/'.$filename;
  if(!move_uploaded_file($upload['tmp_name'],$target))$errors[]='Photo could not be saved. Please try again.';
  else{ $record=$data;$record['slug']=trim(strtolower(preg_replace('/[^a-z0-9]+/i','-',$data['title'])),'-').'-'.bin2hex(random_bytes(4));$record['image']='./assets/uploads/'.$filename;$record['featured']=$data['featured']==='1';$record['is_sample']=false;foreach(['price','area'] as $key)$record[$key]=(float)$data[$key];foreach(['beds','baths'] as $key)$record[$key]=(int)$data[$key];
   $savedDocuments=[];$record['pricing_documents']=[];$record['gallery']=[];$record['videos']=$videos;unset($record['youtube_videos'],$record['youtube_shorts']);
   try{foreach($galleryUploads as $image){$imageName='gallery-'.bin2hex(random_bytes(16)).'.'.$image['extension'];$imagePath=dirname(__DIR__).'/assets/uploads/'.$imageName;if(!move_uploaded_file($image['tmp'],$imagePath))throw new RuntimeException('Gallery upload failed.');$savedDocuments[]=$imagePath;$record['gallery'][]='./assets/uploads/'.$imageName;}foreach($pricingUploads as $document){$documentName='pricing-'.bin2hex(random_bytes(16)).'.'.$document['extension'];$documentPath=dirname(__DIR__).'/assets/uploads/'.$documentName;if(!move_uploaded_file($document['tmp'],$documentPath))throw new RuntimeException('Document upload failed.');$savedDocuments[]=$documentPath;$record['pricing_documents'][]=['url'=>'./assets/uploads/'.$documentName,'name'=>$document['name'],'type'=>$document['type']];}$statement=adminDb()->prepare('INSERT INTO properties (slug,payload) VALUES (?,?)');$statement->execute([$record['slug'],json_encode($record,JSON_THROW_ON_ERROR)]);header('Location: ./properties?created=1');exit;}catch(Throwable $e){foreach($savedDocuments as $savedDocument)if(is_file($savedDocument))unlink($savedDocument);unlink($target);$errors[]='Property could not be saved. Please try again.';}
  }
 }
}
require dirname(__DIR__).'/includes/listings.php';
$properties=listingData();$view='properties';$title='Create property';
require __DIR__.'/header.php'; ?><div class="page-heading"><div><span class="eyebrow">PROPERTY MANAGEMENT</span><h1>Create a property</h1><p>Saved properties appear in the admin inventory and public listing page.</p></div></div><?php if($errors): ?><div class="form-error" role="alert"><ul><?php foreach($errors as $error): ?><li><?= e($error) ?></li><?php endforeach; ?></ul></div><?php endif; ?><?php if(!$types||!$locations): ?><div class="form-error">Add property types and locations in <a href="./catalog">Catalog</a> before creating a property.</div><?php endif; ?><form method="post" enctype="multipart/form-data" class="property-form"><input type="hidden" name="csrf" value="<?= e(adminToken()) ?>"><section class="panel form-section"><h2>Property details</h2><div class="form-grid"><?php foreach(['title'=>['Property title','text',150],'address'=>['Street address (optional)','text',300]] as $key=>$field): ?><label><?= e($field[0]) ?><input name="<?= $key ?>" type="<?= $field[1] ?>" maxlength="<?= $field[2] ?>" value="<?= e($data[$key]) ?>" <?= $key!=='address'?'required':'' ?>></label><?php endforeach; ?><label>Location<select name="city" required><option value="">Choose location</option><?php foreach($locations as $location): ?><option <?= $data['city']===$location?'selected':'' ?>><?= e($location) ?></option><?php endforeach; ?></select></label><label>Property type<select name="type" required><option value="">Choose type</option><?php foreach($types as $type): ?><option <?= $data['type']===$type?'selected':'' ?>><?= e($type) ?></option><?php endforeach; ?></select></label><label>Purpose<select name="purpose" required><option value="">Choose purpose</option><?php foreach(['Rent','Sell'] as $purpose): ?><option <?= $data['purpose']===$purpose?'selected':'' ?>><?= $purpose ?></option><?php endforeach; ?></select></label><label>Price (PKR; monthly for rent)<input type="number" name="price" min="0" max="100000000000" step="0.01" value="<?= e($data['price']) ?>" required></label><?php foreach(['beds'=>'Bedrooms','baths'=>'Bathrooms','area'=>'Area (sq.ft)'] as $key=>$label): ?><label><?= e($label) ?><input type="number" name="<?= $key ?>" min="<?= $key==='area'?'0.01':'0' ?>" max="<?= $key==='area'?'100000000':'100' ?>" step="<?= $key==='area'?'0.01':'1' ?>" value="<?= e($data[$key]) ?>" required></label><?php endforeach; ?><?php foreach(['subtitle'=>'Short description','state'=>'State / province','zip'=>'Postal code','balconies'=>'Balconies','floors'=>'Total floors','parking'=>'Parking'] as $key=>$label): ?><label><?= e($label) ?><input name="<?= $key ?>" value="<?= e($data[$key]) ?>" maxlength="<?= $key==='zip'?30:($key==='subtitle'?200:100) ?>" <?= in_array($key,['balconies','floors'],true)?'type="number" min="0" max="200"':'' ?>></label><?php endforeach; ?></div><label>Description<textarea name="description" rows="5" maxlength="10000" required><?= e($data['description']) ?></textarea></label><label>Amenities (one per line)<textarea name="amenities" rows="3" maxlength="2000" placeholder="Parking&#10;Security&#10;Balcony"><?= e($data['amenities']) ?></textarea></label><label class="checkbox-label"><input type="checkbox" name="featured" value="1" <?= $data['featured']==='1'?'checked':'' ?>> Feature this property</label></section><section class="panel form-section"><h2>Cover photo</h2><p>JPEG, PNG or WebP, up to 5 MB. Re-select your photo if the form reports an error.</p><label>Upload photo<input id="property-photo" type="file" name="photo" accept="image/jpeg,image/png,image/webp" required></label><img id="photo-preview" alt="Selected property photo preview" hidden></section><section class="panel form-section"><h2>Gallery</h2><p>Up to 5 additional JPEG, PNG or WebP images, up to 10 MB each. The cover photo is shown first.</p><label>Upload gallery images<input id="property-gallery" name="gallery[]" type="file" multiple accept="image/jpeg,image/png,image/webp"></label><div id="property-gallery-preview" class="property-upload-previews"></div></section><section class="panel form-section"><h2>YouTube videos</h2><div class="form-grid"><label>Video links (one per line)<textarea name="youtube_videos" rows="4" maxlength="2000" placeholder="https://www.youtube.com/watch?v=..."><?= e($data['youtube_videos']) ?></textarea></label><label>Shorts links (one per line)<textarea name="youtube_shorts" rows="4" maxlength="2000" placeholder="https://www.youtube.com/shorts/..."><?= e($data['youtube_shorts']) ?></textarea></label></div><p>Up to 10 videos or Shorts. YouTube links appear as playable videos on the detail page.</p></section><section class="panel form-section"><h2>Pricing Documents</h2><p>Optional: upload up to 5 PDF or image documents, up to 10 MB each. Re-select files if validation fails.</p><label>Upload pricing documents<input type="file" name="pricing_documents[]" multiple accept="application/pdf,image/jpeg,image/png,image/webp"></label></section><section class="panel form-section"><h2>Nearest Locations</h2><p>Add one place per line, with its distance or travel time after |. Up to 20 places.</p><label>Nearby places (optional)<textarea name="nearest_locations" rows="5" maxlength="4000" placeholder="School | 1 km&#10;Hospital | 5 minutes&#10;Shopping mall | 2 km"><?= e($data['nearest_locations']) ?></textarea></label></section><div class="form-actions"><a href="./properties">Cancel</a><button class="primary-button" type="submit">Create property</button></div></form><?php require __DIR__.'/footer.php'; ?>
